// filter, takeWhile, dropWhile
ast_node_t *test_ext_lists_higher_order() {
  ast_node_t *lst = call("List", {lit_int("1"), lit_int("2"), lit_int("6"),
                                  lit_int("3"), lit_int("8")});

  auto make_pred = [](token_type_t op, const char *bound) {
    return create_lambda_declaration_node(
        create_parameter_node(const_cast<char *>("x"), &node_int),
        create_block_node(
            create_binary_operation_node(op, id("x"), lit_int(bound))));
  };

  return wrap_main({
      val_decl("lst", lst),
      val_decl("flt",
               dot_call(id("lst"), "filter", {make_pred(TOK_GREATER_T, "3")})),
      val_decl("tw",
               dot_call(id("lst"), "takeWhile", {make_pred(TOK_LOWER_T, "5")})),
      val_decl("dw",
               dot_call(id("lst"), "dropWhile", {make_pred(TOK_LOWER_T, "5")})),
      print_call(id("flt")),
      print_call(lit_str("|")),
      print_call(id("tw")),
      print_call(lit_str("|")),
      print_call(id("dw")),
  });
}

